window.PTE_DATA = window.PTE_DATA || {};
PTE_DATA.grammar = [
{
id:"g01", title:"Present tenses", titleAr:"الأزمنة الحاضرة", level:"B1",
why:"في PTE بتحتاج الحاضر البسيط والمستمر والتام في Write Essay و Summarize Written Text، وفي Reading: Fill in the Blanks بيسألوك عن الفعل الصح في الجملة الأكاديمية. غلطة واحدة في الزمن بتخسّرك نقاط Grammar.",
explainEn:"The present simple describes facts, habits and routines: 'Trains run on rails.' The present continuous describes actions happening now or temporary situations: 'The driver is checking the signal.'\n\nThe present perfect (have/has + past participle) connects the past with now. We use it for experiences, results we can see now, and situations that started in the past and continue: 'She has worked here since 2019.'\n\nState verbs (know, believe, want, like, belong, need) are normally NOT used in the continuous form. We say 'I know the answer', not 'I am knowing'.",
explainAr:"الحاضر البسيط بنستخدمه للحقائق والعادات والروتين، زي: القطارات تسير على القضبان. أما الحاضر المستمر فللحدث اللي بيحصل دلوقتي أو الوضع المؤقت. والمضارع التام (have/has + التصريف الثالث) بيربط الماضي بالحاضر: تجربة، أو نتيجة ظاهرة، أو حاجة بدأت في الماضي ولسه مستمرة. في العربية الفعل المضارع بيغطي الحالات كلها (يعمل / يعمل الآن / عمل منذ سنة)، فبنتلخبط في الإنجليزية. كمان أفعال الحالة (know, want, like, need) ما بتتحطش في المستمر، تقول I know مش I am knowing. وانتبه: since مع نقطة زمنية و for مع مدة.",
rules:[
{en:"Present simple: base verb (+s/es for he/she/it) for facts, habits, timetables.", ar:"الحاضر البسيط: الفعل (مع s للمفرد الغائب) للحقائق والعادات والجداول."},
{en:"Present continuous: am/is/are + verb-ing for actions now, temporary situations and trends.", ar:"المستمر: am/is/are + فعل-ing للحدث الآن أو المؤقت أو الاتجاهات المتغيرة."},
{en:"Present perfect: have/has + past participle for experience, recent results and unfinished time (for + period, since + point).", ar:"المضارع التام: have/has + التصريف الثالث للخبرة والنتيجة الحالية والمدة غير المنتهية (for + مدة، since + نقطة بداية)."},
{en:"State verbs (know, believe, need, own, belong) are not used in continuous forms.", ar:"أفعال الحالة (know, believe, need, own) ما بتيجيش في الشكل المستمر."},
{en:"Adverbs of frequency go before the main verb but after 'be': 'She always arrives early.' / 'He is often late.'", ar:"ظروف التكرار قبل الفعل الأساسي وبعد فعل be."}],
examples:[
{en:"Train drivers start work at five in the morning.", ar:"سائقو القطارات يبدؤون العمل في الخامسة صباحًا."},
{en:"The driver is checking the brakes at the moment.", ar:"السائق يفحص الفرامل في هذه اللحظة."},
{en:"Omar has driven this route for ten years.", ar:"عمر يقود على هذا الخط منذ عشر سنوات."},
{en:"Water boils at 100 degrees Celsius.", ar:"الماء يغلي عند 100 درجة مئوية."},
{en:"The number of passengers is rising every year.", ar:"عدد الركاب يرتفع كل سنة."},
{en:"I have never been late for a shift.", ar:"لم أتأخر أبدًا عن مناوبة."},
{en:"She doesn't know the new timetable yet.", ar:"هي لا تعرف الجدول الجديد بعد."}],
traps:[
"I am knowing the answer → I know the answer. (أفعال الحالة لا تأتي مستمرة)",
"He work in a station → He works in a station. (نسيان s مع he/she/it لأن العربية ما فيهاش الحاجة دي)",
"I live here since 2020 → I have lived here since 2020. (since/for تحتاج مضارعًا تامًا؛ في العربية نقول 'أسكن هنا منذ' بالمضارع)",
"She doesn't works → She doesn't work. (بعد does/did الفعل يرجع للأصل)"],
story:"Omar is a train driver. He starts work at five every morning, and he has driven the same route for ten years. Today he is checking a new signal system.",
exercises:[
{type:"mcq", q:"Omar ____ this route since 2016.", options:["drives","is driving","has driven","drove"], answer:2, why:"'Since' + a starting point needs the present perfect.", whyAr:"since مع نقطة بداية تحتاج المضارع التام."},
{type:"mcq", q:"Which sentence is correct?", options:["I am wanting a coffee.","I want a coffee.","I have wanting a coffee.","I wants a coffee."], answer:1, why:"'Want' is a state verb and is not used in the continuous.", whyAr:"want فعل حالة فلا يأتي مستمرًا."},
{type:"mcq", q:"Look! The train ____ into the station.", options:["comes","has come","is coming","come"], answer:2, why:"'Look!' signals an action happening now.", whyAr:"Look! تدل على حدث يحدث الآن."},
{type:"mcq", q:"The sun ____ in the east.", options:["rise","rises","is rising","has risen"], answer:1, why:"A fact needs the present simple, and he/she/it takes -s.", whyAr:"حقيقة علمية: حاضر بسيط مع s."},
{type:"fill", q:"She ____ (work) here since 2019.", answer:["has worked"], why:"Since + point in time = present perfect.", whyAr:"since + نقطة زمنية = مضارع تام."},
{type:"fill", q:"Right now, the engineers ____ (test) the new brakes.", answer:["are testing"], why:"'Right now' = present continuous.", whyAr:"Right now تعني مستمر."},
{type:"fill", q:"My brother never ____ (drink) coffee after noon.", answer:["drinks"], why:"Habit with he: add -s.", whyAr:"عادة مع المفرد الغائب: نضيف s."},
{type:"order", words:["has","she","worked","here","for","years","ten"], answer:"she has worked here for ten years", why:"Subject + has + past participle + for + period.", whyAr:"الفاعل + has + التصريف الثالث + for + المدة."},
{type:"fix", q:"He work at the station since 2015.", answer:"He has worked at the station since 2015.", why:"Needs present perfect with since.", whyAr:"since تحتاج مضارعًا تامًا، و has تعطي worked."},
{type:"fix", q:"I am knowing the answer to this question.", answer:"I know the answer to this question.", why:"Know is a state verb.", whyAr:"know فعل حالة لا يستخدم مستمرًا."}
]},
{
id:"g02", title:"Past simple vs present perfect", titleAr:"الماضي البسيط والمضارع التام", level:"B1",
why:"الفرق بينهم بيظهر في Fill in the Blanks وفي Write Essay لما تحكي عن دراسات وتغيرات (has increased / increased in 2010). اختيار الزمن الغلط بيبان فورًا للمصحح.",
explainEn:"Use the past simple for a finished action at a definite time in the past: 'The company opened a new line in 2015.' We often mention the time (yesterday, last year, in 2010, ago).\n\nUse the present perfect when the time is not important, when the time period is not finished (this week, today, so far), or when the past action has a result now: 'The government has built three new stations this year.'\n\nIn academic writing, the present perfect is common for changes up to now ('Prices have risen sharply'), and the past simple for describing a specific study ('The researchers measured sleep in 2018').",
explainAr:"الماضي البسيط لحدث انتهى في وقت محدد في الماضي (yesterday, in 2010, ago). المضارع التام لما الوقت مش محدد، أو الفترة لسه ما خلصتش (this week, today, so far)، أو لما لحدث الماضي نتيجة ظاهرة دلوقتي. في العربية الفعل الماضي (فعل) بيغطي الحالتين، فبنقول I have seen him yesterday بالغلط. القاعدة الذهبية: لو فيه وقت محدد منتهي (yesterday, last week, ago) استخدم الماضي البسيط ولا تستخدم المضارع التام أبدًا.",
rules:[
{en:"Past simple = finished time: yesterday, last year, in 2010, two days ago, when + past.", ar:"الماضي البسيط مع وقت منتهي: yesterday, last year, in 2010, ago."},
{en:"Present perfect = unfinished time or link to now: today, this week, so far, already, yet, ever, never, just.", ar:"المضارع التام مع فترة لم تنته أو ارتباط بالحاضر: today, so far, already, yet, ever, never, just."},
{en:"Never use the present perfect with a finished-time expression ('I have seen him yesterday' is wrong).", ar:"ممنوع المضارع التام مع تعبير زمني منتهي."},
{en:"'Been to' = visited and returned; 'gone to' = still there.", ar:"been to = زار ورجع، gone to = ذهب وما زال هناك."},
{en:"Ask 'When did you...?' (past simple) but 'Have you ever...?' (present perfect).", ar:"نسأل When did you...؟ بالماضي البسيط، و Have you ever...؟ بالمضارع التام."}],
examples:[
{en:"Omar joined the railway in 2012.", ar:"انضم عمر إلى السكة الحديد عام 2012."},
{en:"Omar has worked for the railway since 2012.", ar:"عمر يعمل في السكة الحديد منذ 2012."},
{en:"I have already sent the report.", ar:"لقد أرسلت التقرير بالفعل."},
{en:"We visited Alexandria last summer.", ar:"زرنا الإسكندرية الصيف الماضي."},
{en:"Have you ever driven a train?", ar:"هل سبق لك أن قدت قطارًا؟"},
{en:"Unemployment has fallen since 2020.", ar:"انخفضت البطالة منذ 2020."},
{en:"She has been to London twice, but she is in Cairo now.", ar:"ذهبت إلى لندن مرتين لكنها الآن في القاهرة."}],
traps:[
"I have seen him yesterday → I saw him yesterday. (yesterday وقت منتهي)",
"I am here since Monday → I have been here since Monday. (مضارع تام وليس حاضر)",
"When have you arrived? → When did you arrive? (When تحتاج ماضيًا بسيطًا)",
"I didn't saw it → I didn't see it. (بعد didn't الفعل في الأصل)"],
story:"Omar joined the railway in 2012. Since then he has driven more than 2,000 trains. Last week he trained a new driver, and she has already passed her first exam.",
exercises:[
{type:"mcq", q:"I ____ my keys yesterday.", options:["have lost","lost","have been losing","lose"], answer:1, why:"Yesterday is finished time.", whyAr:"yesterday وقت منتهي فالماضي البسيط."},
{type:"mcq", q:"Prices ____ sharply this year.", options:["rose","have risen","were rising","did rise"], answer:1, why:"This year is unfinished time.", whyAr:"this year فترة لم تنته."},
{type:"mcq", q:"____ you ever been to London?", options:["Did","Have","Do","Are"], answer:1, why:"Experience up to now: present perfect.", whyAr:"سؤال عن خبرة حتى الآن."},
{type:"mcq", q:"She ____ the report two hours ago.", options:["has finished","finished","finishes","has been finishing"], answer:1, why:"'Ago' needs the past simple.", whyAr:"ago تحتاج ماضيًا بسيطًا."},
{type:"fill", q:"We ____ (live) in this city since 2018.", answer:["have lived"], why:"Since = present perfect.", whyAr:"since = مضارع تام."},
{type:"fill", q:"The company ____ (open) its first office in 1999.", answer:["opened"], why:"In 1999 = finished time.", whyAr:"in 1999 وقت منتهي."},
{type:"fill", q:"I ____ (not finish) my homework yet.", answer:["haven't finished","have not finished"], why:"'Yet' with present perfect.", whyAr:"yet مع المضارع التام."},
{type:"order", words:["did","when","you","arrive","station","at","the"], answer:"when did you arrive at the station", why:"When + did + subject + base verb.", whyAr:"When + did + الفاعل + فعل أصلي."},
{type:"fix", q:"I have seen that film last week.", answer:"I saw that film last week.", why:"Last week is finished time.", whyAr:"last week وقت منتهي."},
{type:"fix", q:"She is a teacher since 2015.", answer:"She has been a teacher since 2015.", why:"Since needs present perfect.", whyAr:"since تحتاج مضارعًا تامًا."}
]},
{
id:"g03", title:"Past perfect & narrative tenses", titleAr:"الماضي التام وأزمنة السرد", level:"B2",
why:"بتظهر في Retell Lecture و Describe Image لما تحكي تسلسل أحداث، وفي Reading للأسئلة اللي فيها ترتيب أحداث. كمان بتفرق في Write Essay لما تعرض أمثلة تاريخية.",
explainEn:"Narrative tenses are used to tell a story or describe past events. The past simple moves the story forward: 'The train stopped.' The past continuous sets the scene or describes an action in progress: 'It was raining when the train stopped.'\n\nThe past perfect (had + past participle) shows an action that happened BEFORE another past action: 'When we arrived, the train had already left.'\n\nThe past perfect continuous (had been + verb-ing) emphasises duration before a past moment: 'He had been driving for six hours when the signal failed.'",
explainAr:"أزمنة السرد بنستخدمها لحكي أحداث الماضي. الماضي البسيط بيحرّك القصة للأمام. الماضي المستمر بيوصف الخلفية أو حدث كان جاريًا لما حصل حدث آخر. الماضي التام (had + التصريف الثالث) لحدث وقع قبل حدث ماضٍ آخر، يعني 'ماضي الماضي'. العربية بتعبّر عنه بـ 'كان قد فعل'. الغلطة الشائعة إننا نستخدم الماضي البسيط لكل شيء فنضيّع ترتيب الأحداث. وكمان ما تستخدمش had بدون داعٍ لو الأحداث متسلسلة بالترتيب.",
rules:[
{en:"Past perfect: had + past participle, for the earlier of two past events.", ar:"الماضي التام: had + التصريف الثالث للحدث الأسبق من حدثين ماضيين."},
{en:"Past continuous: was/were + verb-ing for background or an interrupted action.", ar:"الماضي المستمر للخلفية أو الحدث المقاطَع."},
{en:"Use 'when' + past simple for the interrupting action: 'I was reading when the lights went out.'", ar:"when + ماضي بسيط للحدث الذي قاطع."},
{en:"Time words with past perfect: already, just, by the time, before, after, until.", ar:"كلمات مرتبطة بالماضي التام: already, by the time, before, after."},
{en:"Past perfect continuous: had been + -ing for a long action before a past moment.", ar:"الماضي التام المستمر: had been + ing لمدة سبقت لحظة في الماضي."}],
examples:[
{en:"By the time Omar arrived, the train had left.", ar:"حين وصل عمر كان القطار قد غادر."},
{en:"It was raining when the signal failed.", ar:"كانت تمطر حين تعطلت الإشارة."},
{en:"She had studied English for years before she took the test.", ar:"كانت قد درست الإنجليزية سنوات قبل أن تخوض الاختبار."},
{en:"After he had checked the brakes, he started the engine.", ar:"بعد أن فحص الفرامل شغّل المحرك."},
{en:"They were talking when the manager walked in.", ar:"كانوا يتحدثون حين دخل المدير."},
{en:"He was tired because he had been working all night.", ar:"كان متعبًا لأنه كان يعمل طوال الليل."},
{en:"I realised that I had left my passport at home.", ar:"أدركت أنني نسيت جواز سفري في البيت."}],
traps:[
"When I arrived, the train already left → ...the train had already left. (حدث أسبق يحتاج past perfect)",
"I was seeing him → I saw him. (see لحظي وليس مستمرًا هنا)",
"He had went → He had gone. (بعد had نستخدم التصريف الثالث)",
"After he finished, he had left (أحداث متتالية) → After he had finished, he left. (التام للأسبق فقط)"],
story:"Last Tuesday Omar was driving through a storm when the signal failed. He had been driving for six hours, and he had already reported two earlier faults. He stopped the train safely.",
exercises:[
{type:"mcq", q:"When we got to the platform, the train ____.", options:["left","had left","was leaving","has left"], answer:1, why:"The leaving happened before we got there.", whyAr:"المغادرة حدثت قبل وصولنا."},
{type:"mcq", q:"I ____ a shower when the phone rang.", options:["took","was taking","had taken","take"], answer:1, why:"Action in progress interrupted by another.", whyAr:"حدث جارٍ قاطعه حدث آخر."},
{type:"mcq", q:"She was tired because she ____ all night.", options:["worked","had been working","has worked","works"], answer:1, why:"Duration before a past moment.", whyAr:"مدة سبقت لحظة في الماضي."},
{type:"mcq", q:"After he ____ lunch, he went back to work.", options:["has eaten","had eaten","was eating","eats"], answer:1, why:"Eating happened first.", whyAr:"الأكل حدث أولًا."},
{type:"fill", q:"By the time I arrived, the meeting ____ (start).", answer:["had started"], why:"The meeting started earlier.", whyAr:"الاجتماع بدأ قبل وصولي."},
{type:"fill", q:"It ____ (rain) when we left the house.", answer:["was raining"], why:"Background action.", whyAr:"خلفية للحدث."},
{type:"fill", q:"He ____ (not / see) the film before, so he enjoyed it.", answer:["hadn't seen","had not seen"], why:"Earlier experience.", whyAr:"خبرة سابقة."},
{type:"order", words:["had","the","already","left","train","when","arrived","we"], answer:["the train had already left when we arrived","when we arrived the train had already left"], why:"Past perfect + when + past simple.", whyAr:"ماضٍ تام + when + ماضٍ بسيط."},
{type:"fix", q:"When I got home, my brother already ate dinner.", answer:"When I got home, my brother had already eaten dinner.", why:"Earlier event needs past perfect.", whyAr:"الأكل أسبق فيحتاج had eaten."},
{type:"fix", q:"She had went to Paris before she moved to Rome.", answer:"She had gone to Paris before she moved to Rome.", why:"Past participle of go is gone.", whyAr:"التصريف الثالث لـ go هو gone."}
]},
{
id:"g04", title:"Passives", titleAr:"المبني للمجهول", level:"B2",
why:"الأكاديمي بيحب المبني للمجهول (the study was carried out). هتحتاجه في Write Essay و Summarize Written Text وفي Fill in the Blanks، والمصحح بيدّي نقاط على الأسلوب الرسمي.",
explainEn:"We use the passive when the action is more important than the person who does it, when the doer is unknown, or in formal and academic writing. The passive is formed with be + past participle: 'The bridge was built in 1990.'\n\nThe tense is shown by the verb 'be': is built (present simple), was built (past simple), has been built (present perfect), will be built (future), is being built (present continuous). We add 'by + agent' only when the agent is important.\n\nOnly transitive verbs can be passive. Verbs such as happen, occur, arrive and die have no passive form: we cannot say 'The accident was happened'.",
explainAr:"بنستخدم المبني للمجهول لما الحدث أهم من الفاعل، أو الفاعل غير معروف، أو في الكتابة الرسمية والأكاديمية. التركيب: be + التصريف الثالث، والزمن بيظهر في فعل be. بنضيف by + الفاعل بس لو مهم. في العربية المبني للمجهول بيتم بتغيير حركات الفعل (كُتِبَ)، وفي الإنجليزية بتغيّر التركيب كله. انتبه: الأفعال اللازمة (happen, occur, arrive, die, seem) ما بيتعملهاش مبني للمجهول، فما نقولش 'was happened'.",
rules:[
{en:"Form: subject + be (in the right tense) + past participle.", ar:"التركيب: الفاعل + be بالزمن المناسب + التصريف الثالث."},
{en:"Add 'by + agent' only if the agent is new or important information.", ar:"نضيف by + الفاعل فقط إذا كان مهمًا."},
{en:"Modal passive: modal + be + past participle ('The test must be completed').", ar:"المبني للمجهول مع الأفعال الناقصة: modal + be + التصريف الثالث."},
{en:"Intransitive verbs (happen, occur, arrive, die, appear) cannot be passive.", ar:"الأفعال اللازمة لا يُبنى منها مجهول."},
{en:"Reporting passives: 'It is believed that...' / 'X is thought to be...' are common in academic writing.", ar:"صيغ مثل It is believed that شائعة في الأكاديمي."}],
examples:[
{en:"The new station was opened by the mayor.", ar:"افتُتحت المحطة الجديدة على يد العمدة."},
{en:"English is spoken in many countries.", ar:"تُتحدث الإنجليزية في دول كثيرة."},
{en:"The tracks are being repaired this week.", ar:"تُصلح القضبان هذا الأسبوع."},
{en:"The results have been published online.", ar:"نُشرت النتائج على الإنترنت."},
{en:"The report must be submitted by Friday.", ar:"يجب تسليم التقرير قبل الجمعة."},
{en:"It is believed that sleep improves memory.", ar:"يُعتقد أن النوم يحسّن الذاكرة."},
{en:"The experiment was carried out in 2019.", ar:"أُجريت التجربة عام 2019."}],
traps:[
"The accident was happened → The accident happened. (happen لازم)",
"The letter wrote by him → The letter was written by him. (نسيان be والتصريف الثالث)",
"The cake was ate → The cake was eaten. (التصريف الثالث لـ eat هو eaten)",
"The report must submitted → The report must be submitted. (نسيان be بعد modal)"],
story:"The railway line was built in 1920. Last year the tracks were repaired, and a new station is being constructed now. Omar's team has been told that the line will be reopened next month.",
exercises:[
{type:"mcq", q:"The bridge ____ in 1995.", options:["built","was built","is built","has built"], answer:1, why:"Past simple passive.", whyAr:"مبني للمجهول ماضٍ بسيط."},
{type:"mcq", q:"Which sentence is correct?", options:["The accident was happened last night.","The accident happened last night.","The accident has been happened.","The accident is happening yesterday."], answer:1, why:"Happen is intransitive.", whyAr:"happen فعل لازم لا يُبنى للمجهول."},
{type:"mcq", q:"The tracks ____ at the moment.", options:["repair","are repaired","are being repaired","have repaired"], answer:2, why:"Present continuous passive.", whyAr:"مجهول مضارع مستمر."},
{type:"mcq", q:"The form ____ before Friday.", options:["must submit","must be submitted","must submitted","must be submit"], answer:1, why:"modal + be + past participle.", whyAr:"modal + be + التصريف الثالث."},
{type:"fill", q:"The results ____ (publish) last month.", answer:["were published"], why:"Past simple passive.", whyAr:"مجهول ماضٍ بسيط."},
{type:"fill", q:"English ____ (speak) all over the world.", answer:["is spoken"], why:"Present simple passive.", whyAr:"مجهول مضارع بسيط."},
{type:"fill", q:"The new line ____ (open) next year.", answer:["will be opened"], why:"Future passive.", whyAr:"مجهول مستقبل."},
{type:"order", words:["was","built","the","in","station","1990"], answer:"the station was built in 1990", why:"Subject + was + past participle.", whyAr:"الفاعل + was + التصريف الثالث."},
{type:"fix", q:"The experiment carried out by scientists in 2018.", answer:"The experiment was carried out by scientists in 2018.", why:"Missing 'was'.", whyAr:"ينقص الفعل was."},
{type:"fix", q:"The window was broke by the storm.", answer:"The window was broken by the storm.", why:"Past participle of break is broken.", whyAr:"التصريف الثالث broken."}
]},
{
id:"g05", title:"Relative clauses", titleAr:"جمل الصلة", level:"B2",
why:"جمل الصلة بتخليك تدمج جمل قصيرة في جملة واحدة قوية، وده مطلوب في Summarize Written Text (جملة واحدة) وفي Write Essay. وبتظهر كمان في Fill in the Blanks (who/which/where).",
explainEn:"Relative clauses give more information about a noun. A defining clause identifies which person or thing we mean and has no commas: 'The driver who caused the delay was new.' A non-defining clause adds extra information and is separated by commas: 'Omar, who lives in Giza, drives this train.'\n\nUse who for people, which for things, where for places, whose for possession. 'That' can replace who/which in defining clauses only. In defining clauses, the relative pronoun can be dropped when it is the object: 'The book (that) I read was long.'\n\nDo not repeat the pronoun: we say 'the man who lives here', not 'the man who he lives here'.",
explainAr:"جملة الصلة بتدي معلومة عن اسم. النوع المحدِّد (defining) لازم لتعريف المقصود وبدون فواصل. النوع غير المحدِّد (non-defining) معلومة إضافية بين فاصلتين، ومعاه ما ينفعش that. استخدم who للعاقل و which لغير العاقل و where للمكان و whose للملكية. أهم فخ للعرب: في العربية الاسم الموصول (الذي) بعده ضمير عائد (الرجل الذي رأيته**ه**)، أما في الإنجليزية ما نكررش الضمير: The man who I saw، مش who I saw him. كمان ما نقولش person which بل person who.",
rules:[
{en:"who = people; which = things; where = places; whose = possession; that = people/things (defining only).", ar:"who للعاقل، which لغير العاقل، where للمكان، whose للملكية، that للمحدِّد فقط."},
{en:"Non-defining clauses need commas and never use 'that'.", ar:"غير المحدِّدة بين فاصلتين ولا تأخذ that."},
{en:"The pronoun may be omitted when it is the object of the clause.", ar:"يجوز حذف الضمير الموصول إذا كان مفعولًا."},
{en:"Do not repeat the subject or object pronoun inside the clause.", ar:"لا نكرر الضمير العائد داخل الجملة."},
{en:"Preposition + whom/which is formal: 'the company for which she works'.", ar:"حرف الجر + whom/which أسلوب رسمي."}],
examples:[
{en:"The driver who caused the delay was new.", ar:"السائق الذي تسبب في التأخير كان جديدًا."},
{en:"Omar, who lives in Giza, drives the 6 a.m. train.", ar:"عمر، الذي يسكن في الجيزة، يقود قطار السادسة."},
{en:"This is the station where we first met.", ar:"هذه المحطة التي التقينا فيها أول مرة."},
{en:"The report, which was published in May, shows a rise in costs.", ar:"التقرير، الذي نُشر في مايو، يظهر ارتفاعًا في التكاليف."},
{en:"Researchers whose studies are well known often get funding.", ar:"الباحثون الذين تشتهر دراساتهم يحصلون غالبًا على تمويل."},
{en:"The book I borrowed was very useful.", ar:"الكتاب الذي استعرته كان مفيدًا جدًا."},
{en:"A primary school is a place where young children study.", ar:"المدرسة الابتدائية مكان يدرس فيه الصغار."}],
traps:[
"The man who I saw him → The man (who) I saw. (لا تكرر الضمير)",
"A person which helps → A person who helps. (which لغير العاقل)",
"Cairo, that is huge, is crowded → Cairo, which is huge, is crowded. (that ممنوع بعد فاصلة)",
"The house where I live in → The house where I live / the house I live in. (where يغني عن in)"],
story:"Omar, who has driven trains for ten years, trains new drivers. The woman who started last week is the first student he has ever taught. The depot where they practise is near Cairo.",
exercises:[
{type:"mcq", q:"The woman ____ lives next door is a doctor.", options:["which","who","where","whose"], answer:1, why:"Person: who.", whyAr:"للعاقل who."},
{type:"mcq", q:"Cairo, ____ is very large, is the capital.", options:["that","who","which","where"], answer:2, why:"Non-defining, thing: which, not that.", whyAr:"غير محدِّدة وغير عاقل: which."},
{type:"mcq", q:"Which sentence is correct?", options:["The man who I met him is kind.","The man I met is kind.","The man which I met is kind.","The man who he met is kind."], answer:1, why:"No repeated pronoun; person.", whyAr:"بلا ضمير مكرر."},
{type:"mcq", q:"That is the town ____ I was born.", options:["which","who","where","whose"], answer:2, why:"Place: where.", whyAr:"مكان: where."},
{type:"fill", q:"The scientist ____ research won the prize is my aunt. (relative pronoun)", answer:["whose"], why:"Possession: whose.", whyAr:"ملكية: whose."},
{type:"fill", q:"The laptop, ____ I bought last year, has stopped working. (relative pronoun)", answer:["which"], why:"Non-defining, thing.", whyAr:"غير محدِّدة، شيء."},
{type:"fill", q:"A library is a place ____ you can borrow books. (relative pronoun)", answer:["where"], why:"Place: where.", whyAr:"مكان: where."},
{type:"order", words:["the","who","teacher","taught","me","retired"], answer:"the teacher who taught me retired", why:"Noun + who + clause + main verb.", whyAr:"الاسم + who + الجملة + الفعل الرئيسي."},
{type:"fix", q:"She is a person which helps everyone.", answer:["She is a person who helps everyone.","She is a person that helps everyone."], why:"Use who for people.", whyAr:"للعاقل who."},
{type:"fix", q:"The book that I read it was long.", answer:["The book that I read was long.","The book I read was long."], why:"Do not repeat the object pronoun.", whyAr:"لا نكرر الضمير."}
]},
{
id:"g06", title:"Conditionals 0, 1 and 2", titleAr:"الجمل الشرطية (صفر، أول، ثاني)", level:"B1",
why:"الشرطية بتظهر في Write Essay لما تعرض نتائج وحلول ('If governments invest...')، وفي Fill in the Blanks، وفي Speaking لما تشرح سيناريو.",
explainEn:"The zero conditional uses present + present for general truths: 'If you heat ice, it melts.' The first conditional uses if + present simple, will + base verb for real or likely future situations: 'If it rains, we will cancel the trip.'\n\nThe second conditional uses if + past simple, would + base verb for unreal or unlikely situations in the present or future: 'If I had more time, I would learn Spanish.' With be, we often use 'were' for all persons in formal English: 'If I were you, I would apply.'\n\nDo not use will after if in the if-clause. Use 'unless' to mean 'if ... not'.",
explainAr:"الصفر للحقائق العامة: if + مضارع، مضارع. الأول للمستقبل الممكن: if + مضارع بسيط، will + فعل. الثاني للمستحيل أو الخيالي في الحاضر والمستقبل: if + ماضٍ بسيط، would + فعل. في العربية 'إذا / لو' بتغطي كل ده، فبنقول if it will rain بالغلط. القاعدة: ما نحطش will بعد if. وفي الثاني الماضي مش معناه ماضٍ حقيقيًا، بل 'بعد عن الواقع'. unless = if not فما نكرر النفي معاها.",
rules:[
{en:"Zero: if + present simple, present simple (general truths).", ar:"صفر: if + مضارع، مضارع (حقائق عامة)."},
{en:"First: if + present simple, will + base verb (real future).", ar:"أول: if + مضارع، will + فعل (مستقبل ممكن)."},
{en:"Second: if + past simple, would + base verb (unreal present/future).", ar:"ثانٍ: if + ماضٍ بسيط، would + فعل (غير واقعي)."},
{en:"Never use will/would in the if-clause.", ar:"لا نستخدم will/would في جملة if."},
{en:"'Unless' = 'if not'; do not add another negative.", ar:"unless = if not ولا نضيف نفيًا آخر."},
{en:"Use 'were' for all persons in formal second conditionals.", ar:"نستخدم were مع كل الضمائر في الرسمي."}],
examples:[
{en:"If you press this button, the doors open.", ar:"إذا ضغطت هذا الزر تنفتح الأبواب."},
{en:"If the signal fails, the train will stop automatically.", ar:"إذا تعطلت الإشارة سيتوقف القطار تلقائيًا."},
{en:"If I were the manager, I would increase the budget.", ar:"لو كنت المدير لزدت الميزانية."},
{en:"If prices rise, fewer people will buy tickets.", ar:"إذا ارتفعت الأسعار سيشتري تذاكر أقل عددًا من الناس."},
{en:"Unless you hurry, you will miss the train.", ar:"ما لم تسرع ستفوتك الرحلة."},
{en:"If she studied harder, she would pass the exam.", ar:"لو ذاكرت أكثر لنجحت في الاختبار."},
{en:"If governments invested in rail, pollution would fall.", ar:"لو استثمرت الحكومات في السكك الحديدية لانخفض التلوث."}],
traps:[
"If it will rain, we stay home → If it rains, we will stay home. (لا will بعد if)",
"If I would have money, I would buy a car → If I had money, I would buy a car.",
"Unless you don't study, you fail → Unless you study, you will fail. (unless تحمل النفي)",
"If I am you → If I were you. (نصيحة غير واقعية)"],
story:"If Omar finishes his shift early, he will visit his mother. If he had a day off every week, he would spend more time with his family. But on a train, if the brakes fail, the driver must stay calm.",
exercises:[
{type:"mcq", q:"If you heat water to 100°C, it ____.", options:["will boil","boils","would boil","boiled"], answer:1, why:"General truth: zero conditional.", whyAr:"حقيقة عامة."},
{type:"mcq", q:"If it rains tomorrow, we ____ the match.", options:["cancel","would cancel","will cancel","cancelled"], answer:2, why:"First conditional.", whyAr:"شرطي أول."},
{type:"mcq", q:"If I ____ rich, I would travel the world.", options:["am","was being","were","will be"], answer:2, why:"Second conditional, unreal.", whyAr:"شرطي ثانٍ."},
{type:"mcq", q:"____ you leave now, you will miss the train.", options:["If not","Unless","Without","Only"], answer:1, why:"Unless = if not.", whyAr:"unless = if not."},
{type:"fill", q:"If she ____ (study) harder, she would pass.", answer:["studied"], why:"Past simple in the if-clause.", whyAr:"ماضٍ بسيط بعد if."},
{type:"fill", q:"If the price goes up next month, fewer people ____ (buy) it.", answer:["will buy"], why:"First conditional.", whyAr:"شرطي أول."},
{type:"fill", q:"If I ____ (be) you, I would apply for that job.", answer:["were"], why:"'Were' for advice.", whyAr:"were للنصيحة."},
{type:"order", words:["if","you","will","study","pass","you"], answer:["if you study you will pass","you will pass if you study"], why:"if + present, will + base.", whyAr:"if + مضارع، will + فعل."},
{type:"fix", q:"If it will rain, we will stay home.", answer:"If it rains, we will stay home.", why:"No will in the if-clause.", whyAr:"لا will بعد if."},
{type:"fix", q:"If I would have more time, I would learn French.", answer:"If I had more time, I would learn French.", why:"Past simple in the if-clause.", whyAr:"ماضٍ بسيط بعد if."}
]},
{
id:"g07", title:"Third & mixed conditionals", titleAr:"الشرطي الثالث والمختلط", level:"C1",
why:"الثالث والمختلط من علامات C1 في Write Essay وفي Fill in the Blanks. استخدامهم الصحيح في خاتمة المقال ('If governments had acted earlier...') بيرفع جودة الأسلوب.",
explainEn:"The third conditional talks about unreal situations in the past: if + past perfect, would have + past participle. 'If he had left earlier, he would have caught the train.' The past did not happen that way, so we imagine a different result.\n\nThe mixed conditional combines two time references. The most common type is an unreal past cause with a present result: 'If I had studied medicine, I would be a doctor now.' The other is a present state with a past result: 'If she were more careful, she wouldn't have made that mistake.'\n\nIn formal writing we can invert and drop if: 'Had he left earlier, he would have caught the train.'",
explainAr:"الشرطي الثالث عن الماضي المستحيل تغييره: if + past perfect، would have + التصريف الثالث. يعني 'لو كان حصل كذا لكان حصل كذا'، وهو بيعبّر عن الندم أو اللوم. المختلط بيجمع زمنين: سبب في الماضي ونتيجة في الحاضر (If I had studied medicine, I would be a doctor now) أو العكس. العربية بتستخدم 'لو' + كان، فالمتعلم بيحط would بعد if وده غلط. وفي الرسمي نقلب الترتيب ونحذف if: Had he left earlier.",
rules:[
{en:"Third: if + past perfect, would (could/might) have + past participle.", ar:"ثالث: if + past perfect، would have + التصريف الثالث."},
{en:"Mixed (past → present): if + past perfect, would + base verb.", ar:"مختلط (سبب ماضٍ ونتيجة حاضرة): if + past perfect، would + فعل."},
{en:"Mixed (present → past): if + past simple, would have + past participle.", ar:"مختلط (حالة حاضرة ونتيجة ماضية): if + ماضٍ بسيط، would have + التصريف الثالث."},
{en:"Never use 'would have' in the if-clause.", ar:"لا would have في جملة if."},
{en:"Formal inversion: Had + subject + past participle, ...", ar:"قلب رسمي: Had + الفاعل + التصريف الثالث."}],
examples:[
{en:"If he had left earlier, he would have caught the train.", ar:"لو غادر مبكرًا لكان لحق بالقطار."},
{en:"If I had studied medicine, I would be a doctor now.", ar:"لو درست الطب لكنت طبيبًا الآن."},
{en:"If she were more careful, she wouldn't have made that error.", ar:"لو كانت أكثر حرصًا ما ارتكبت ذلك الخطأ."},
{en:"Had the government acted sooner, the crisis might have been avoided.", ar:"لو تحركت الحكومة مبكرًا لربما أمكن تجنب الأزمة."},
{en:"If they hadn't cut the budget, the line would be open today.", ar:"لو لم يخفضوا الميزانية لكان الخط مفتوحًا اليوم."},
{en:"If I had known, I would have told you.", ar:"لو كنت أعلم لأخبرتك."},
{en:"We could have finished on time if we had started earlier.", ar:"كان بإمكاننا الانتهاء في الوقت لو بدأنا مبكرًا."}],
traps:[
"If I would have known, I would have told you → If I had known, I would have told you.",
"If I had a car, I would have gone (عن ماضٍ) → If I had had a car, I would have gone.",
"If he studied, he would have passed → If he had studied, he would have passed.",
"I wish I studied more (ندم على الماضي) → I wish I had studied more."],
story:"Last winter a signal failed and Omar's train was delayed. If the engineers had checked the system, the delay wouldn't have happened. If the company had invested more, the network would be safer today.",
exercises:[
{type:"mcq", q:"If she ____ the alarm, she would have caught the bus.", options:["heard","had heard","would hear","has heard"], answer:1, why:"Third conditional: past perfect.", whyAr:"ثالث: past perfect."},
{type:"mcq", q:"If I had saved money, I ____ a house now.", options:["will buy","would have bought","would own","had owned"], answer:2, why:"Mixed: past cause, present result.", whyAr:"مختلط: سبب ماضٍ ونتيجة حاضرة."},
{type:"mcq", q:"Choose the correct sentence.", options:["If I would have known, I would have helped.","If I had known, I would have helped.","If I knew, I would have helped.","If I have known, I would help."], answer:1, why:"No would in the if-clause.", whyAr:"لا would بعد if."},
{type:"mcq", q:"____ the government acted sooner, the crisis would have been avoided.", options:["Has","Had","Would","If had"], answer:1, why:"Inverted third conditional.", whyAr:"قلب رسمي."},
{type:"fill", q:"If they had trained more, they ____ (win) the match.", answer:["would have won"], why:"Third conditional result.", whyAr:"نتيجة الشرطي الثالث."},
{type:"fill", q:"If he ____ (not / miss) the bus, he would have arrived on time.", answer:["hadn't missed","had not missed"], why:"Past perfect negative.", whyAr:"past perfect منفي."},
{type:"fill", q:"If I were more patient, I ____ (not / shout) at him yesterday.", answer:["wouldn't have shouted","would not have shouted"], why:"Mixed: present state, past result.", whyAr:"مختلط."},
{type:"order", words:["had","if","known","I","I","would","told","have","you"], answer:["if I had known I would have told you","I would have told you if I had known"], why:"if + past perfect, would have + pp.", whyAr:"if + past perfect، would have + pp."},
{type:"fix", q:"If I would have studied, I would have passed.", answer:"If I had studied, I would have passed.", why:"Past perfect in the if-clause.", whyAr:"past perfect بعد if."},
{type:"fix", q:"If she studied harder last year, she would have passed.", answer:"If she had studied harder last year, she would have passed.", why:"Past time needs past perfect.", whyAr:"الماضي يحتاج past perfect."}
]},
{
id:"g08", title:"Modals of speculation & deduction", titleAr:"الأفعال الناقصة للتخمين والاستنتاج", level:"B2",
why:"بتظهر في Listening (Highlight Incorrect Words و Multiple Choice) وفي Write Essay لما تتكلم بتحفظ (hedging) زي 'this may lead to'. استخدام hedging بيخلي أسلوبك أكاديمي.",
explainEn:"We use modal verbs to show how certain we are. For present deduction: must (about 90-95% sure it is true), might / may / could (possible), can't / couldn't (almost sure it is not true). 'He must be tired; he has worked all night.' 'That can't be right.'\n\nFor the past we use modal + have + past participle: 'She must have left early', 'He might have forgotten', 'They can't have arrived yet'. For actions in progress: modal + be + -ing: 'He must be sleeping.'\n\nNote: for negative deduction we use can't, not 'mustn't'. 'Mustn't' means prohibition. In academic writing, may, might and could are used to be careful (hedging): 'This may result in higher costs.'",
explainAr:"الأفعال الناقصة بتعبّر عن درجة اليقين. للحاضر: must (متأكد تقريبًا إنه صحيح)، may/might/could (محتمل)، can't (شبه مستحيل). للماضي: modal + have + التصريف الثالث. العربية بتستخدم 'لا بد أن' و 'ربما' و 'لا يمكن أن'. فخ كبير: نفي must للاستنتاج هو can't وليس mustn't (لأن mustn't معناها ممنوع). وفي الكتابة الأكاديمية نستخدم may/might/could للحذر (hedging) بدل الجزم، مثل: This may lead to...",
rules:[
{en:"Present certainty: must + base verb; impossibility: can't / couldn't + base verb.", ar:"يقين حاضر: must، استحالة: can't/couldn't."},
{en:"Possibility: may / might / could + base verb.", ar:"احتمال: may/might/could."},
{en:"Past deduction: must / might / can't + have + past participle.", ar:"استنتاج الماضي: modal + have + التصريف الثالث."},
{en:"Action in progress: modal + be + verb-ing.", ar:"حدث جارٍ: modal + be + ing."},
{en:"Negative deduction = can't, never mustn't (mustn't = prohibition).", ar:"نفي الاستنتاج can't وليس mustn't."},
{en:"Use may / might / could to hedge academic claims.", ar:"استخدم may/might/could للحذر في الكتابة."}],
examples:[
{en:"He must be tired; he has driven all night.", ar:"لا بد أنه متعب؛ فقد قاد طوال الليل."},
{en:"That can't be the right platform.", ar:"لا يمكن أن يكون هذا الرصيف الصحيح."},
{en:"She might have missed the train.", ar:"ربما فاتها القطار."},
{en:"The delay could be caused by the weather.", ar:"قد يكون التأخير بسبب الطقس."},
{en:"They must have left already; the office is empty.", ar:"لا بد أنهم غادروا؛ المكتب فارغ."},
{en:"This policy may lead to higher prices.", ar:"قد تؤدي هذه السياسة إلى ارتفاع الأسعار."},
{en:"He can't have finished; he started ten minutes ago.", ar:"لا يمكن أن يكون قد أنهى؛ فقد بدأ منذ عشر دقائق."}],
traps:[
"He mustn't be at home (استنتاج) → He can't be at home.",
"She must left → She must have left. (نسيان have)",
"It can be true (تأكد) → It must be true. (can لا تعبر عن يقين)",
"He may to come → He may come. (لا to بعد modal)"],
story:"Omar's phone is off and his train is late. He must be in a tunnel. He can't have forgotten the shift, because he is always on time. He might have had a signal problem.",
exercises:[
{type:"mcq", q:"She has been working since 6 a.m. She ____ be exhausted.", options:["must","can't","might not","shouldn't"], answer:0, why:"Strong positive deduction.", whyAr:"استنتاج قوي."},
{type:"mcq", q:"That ____ be Omar. He is in Alexandria today.", options:["must","can't","might","should"], answer:1, why:"Impossible: can't.", whyAr:"مستحيل: can't."},
{type:"mcq", q:"The lights are off. They ____ gone to bed.", options:["must have","must","can have","may to have"], answer:0, why:"Past deduction: must have + pp.", whyAr:"استنتاج ماضٍ."},
{type:"mcq", q:"Which is a hedge in academic writing?", options:["This will fail.","This may cause problems.","This always causes problems.","This definitely fails."], answer:1, why:"May shows possibility.", whyAr:"may تدل على احتمال."},
{type:"fill", q:"He isn't answering. He ____ (might / sleep) now. Use might + be + verb-ing.", answer:["might be sleeping"], why:"Possibility in progress.", whyAr:"احتمال لحدث جارٍ."},
{type:"fill", q:"She ____ (can't / finish) already; she only started five minutes ago. Use can't + have + pp.", answer:["can't have finished","cannot have finished"], why:"Past impossibility.", whyAr:"استحالة في الماضي."},
{type:"fill", q:"The road is wet. It ____ (must / rain) last night. Use must + have + pp.", answer:["must have rained"], why:"Past deduction.", whyAr:"استنتاج ماضٍ."},
{type:"order", words:["have","he","might","the","missed","train"], answer:"he might have missed the train", why:"Modal + have + pp.", whyAr:"modal + have + pp."},
{type:"fix", q:"He mustn't be at home; his car is gone.", answer:["He can't be at home; his car is gone.","He cannot be at home; his car is gone."], why:"Negative deduction = can't.", whyAr:"نفي الاستنتاج can't."},
{type:"fix", q:"She must left early.", answer:"She must have left early.", why:"Past deduction needs have + pp.", whyAr:"نحتاج have + pp."}
]},
{
id:"g09", title:"Future forms", titleAr:"صيغ المستقبل", level:"B1",
why:"في Write Essay بتحتاج تتنبأ وتقترح حلول (will / is likely to)، وفي Speaking (Describe Image) بتتوقع اتجاهات. اختيار صيغة المستقبل الصح بيبين تحكمك في اللغة.",
explainEn:"English has several ways to talk about the future. 'Will' is used for predictions, instant decisions and promises: 'I'll help you.' 'Be going to' is used for plans and intentions and for predictions based on evidence: 'Look at those clouds. It's going to rain.'\n\nThe present continuous is used for fixed arrangements: 'I'm meeting the manager at ten.' The present simple is used for timetables: 'The train leaves at 8.15.' The future continuous (will be + -ing) describes an action in progress at a future time, and the future perfect (will have + pp) describes an action completed before a future time: 'By 2030, they will have built the new line.'\n\nAfter time words such as when, as soon as, before, after, until, use the present simple, not will.",
explainAr:"في الإنجليزية صيغ كتير للمستقبل مش صيغة واحدة. will للتنبؤ والقرار اللحظي والوعد. going to للخطة والنية والتنبؤ المبني على دليل ظاهر. المضارع المستمر للمواعيد المرتبة. المضارع البسيط للجداول الثابتة. المستقبل المستمر والتام للأحداث الجارية أو المنتهية قبل وقت مستقبلي. في العربية بنضيف 'سـ' أو 'سوف' لكل شيء. فخ مهم: بعد when/as soon as/before/until نستخدم المضارع البسيط وليس will.",
rules:[
{en:"Will: predictions, instant decisions, promises, offers.", ar:"will: تنبؤ، قرار لحظي، وعد، عرض."},
{en:"Be going to: plans and predictions with present evidence.", ar:"going to: خطط ونوايا وتنبؤ بدليل."},
{en:"Present continuous: personal arrangements; present simple: timetables.", ar:"مستمر للترتيبات الشخصية، وبسيط للجداول."},
{en:"Future continuous: will be + -ing; future perfect: will have + pp.", ar:"مستقبل مستمر وتام."},
{en:"After when / as soon as / before / until / if, use present simple for future meaning.", ar:"بعد ظروف الزمن نستخدم المضارع البسيط."},
{en:"Likely / certain / bound + to are common in academic predictions.", ar:"likely to وغيرها للتنبؤ الأكاديمي."}],
examples:[
{en:"I'll carry your bag.", ar:"سأحمل حقيبتك."},
{en:"We are going to build a new depot next year.", ar:"سنبني مستودعًا جديدًا العام القادم."},
{en:"I'm meeting the engineer at ten tomorrow.", ar:"سأقابل المهندس غدًا في العاشرة."},
{en:"The train leaves at 8.15 from platform two.", ar:"يغادر القطار الساعة 8:15 من الرصيف الثاني."},
{en:"By 2030, they will have completed the metro line.", ar:"بحلول 2030 سيكونون قد أكملوا خط المترو."},
{en:"I'll call you as soon as I arrive.", ar:"سأتصل بك فور وصولي."},
{en:"Sea levels are likely to rise over the next century.", ar:"من المرجح أن يرتفع مستوى البحر خلال القرن القادم."}],
traps:[
"When I will arrive, I call you → When I arrive, I'll call you.",
"I will to go → I will go. (لا to بعد will)",
"Look at the clouds! It will rain → ...It's going to rain. (دليل ظاهر)",
"Tomorrow I will meeting him → Tomorrow I'm meeting him."],
story:"Omar is going to retire in five years. Next month he is taking a long holiday. By the time he retires, he will have driven for thirty years, and the company will have replaced all the old trains.",
exercises:[
{type:"mcq", q:"Look at those black clouds! It ____ rain.", options:["will","is going to","rains","is raining"], answer:1, why:"Prediction based on evidence.", whyAr:"تنبؤ بدليل."},
{type:"mcq", q:"The phone is ringing. I ____ answer it.", options:["will","am going to","answer","am answering"], answer:0, why:"Instant decision.", whyAr:"قرار لحظي."},
{type:"mcq", q:"I'll text you as soon as I ____.", options:["will arrive","arrive","arrived","am arriving"], answer:1, why:"Present simple after as soon as.", whyAr:"مضارع بسيط بعد as soon as."},
{type:"mcq", q:"By 2035, the city ____ a new metro.", options:["will build","will have built","is building","builds"], answer:1, why:"Completed before a future time.", whyAr:"منتهٍ قبل وقت مستقبلي."},
{type:"fill", q:"The train ____ (leave) at 9.30 tomorrow. (timetable)", answer:["leaves"], why:"Timetable: present simple.", whyAr:"جدول: مضارع بسيط."},
{type:"fill", q:"We ____ (meet) the client at 3 p.m. on Friday. (arrangement)", answer:["are meeting"], why:"Arrangement: present continuous.", whyAr:"ترتيب: مستمر."},
{type:"fill", q:"Don't call me at 8. I ____ (sleep) then. (future continuous)", answer:["will be sleeping"], why:"Action in progress at that time.", whyAr:"حدث جارٍ في ذلك الوقت."},
{type:"order", words:["is","going","he","to","retire","soon"], answer:"he is going to retire soon", why:"Subject + be + going to + base verb.", whyAr:"الفاعل + be + going to + فعل."},
{type:"fix", q:"When I will see him, I will tell him.", answer:"When I see him, I will tell him.", why:"No will after when.", whyAr:"لا will بعد when."},
{type:"fix", q:"I will to call you tomorrow.", answer:"I will call you tomorrow.", why:"No 'to' after will.", whyAr:"لا to بعد will."}
]},
{
id:"g10", title:"Articles: a, the, zero", titleAr:"أدوات التعريف والتنكير", level:"B1",
why:"دي أكبر مشكلة عند المتحدثين بالعربية، لأن العربية فيها 'ال' فقط ومفيش أداة تنكير. بتكلّفك نقاط في Write Essay، Summarize Written Text، و Fill in the Blanks. الوحدة دي أولوية رقم 1.",
explainEn:"Use 'a / an' for a singular countable noun when it is not specific or is mentioned for the first time: 'I saw a train.' Use 'the' when both speaker and listener know which one: because it was mentioned before ('The train was late'), because it is unique (the sun, the government), or because it is defined ('the station in Giza').\n\nUse NO article (zero article) with plural and uncountable nouns in general statements: 'Trains are fast.' 'Information is important.' Also with most proper names, languages, subjects and meals: 'Egypt', 'English', 'Biology', 'breakfast'.\n\nUse 'the' with superlatives, ordinal numbers, rivers, seas, mountain ranges, and countries with 'republic / kingdom / states': the Nile, the Red Sea, the United States.",
explainAr:"العربية فيها 'ال' للتعريف ومفيهاش أداة تنكير مكتوبة، ولذلك المتعلم العربي بينسى a/an أو بيحط the في أماكن غلط. a/an مع المفرد المعدود غير المحدد أو أول ذكر. the مع المعروف للطرفين: ذُكر قبل كده، أو فريد (the sun)، أو محدد بوصف. ولا حاجة (zero) مع الجمع وغير المعدود لما بنتكلم عموميًا، مثل: Trains are fast (القطارات سريعة، وليس The trains). الفرق مهم: في العربية نقول 'القطارات سريعة' بالـ 'ال' فنترجمها خطأ The trains are fast. مع الأعلام والعلوم واللغات والوجبات: بدون أداة.",
rules:[
{en:"a / an: singular countable, first mention or not specific; use 'an' before vowel sounds.", ar:"a/an للمفرد المعدود غير المحدد أو أول ذكر، وan قبل صوت متحرك."},
{en:"the: specific/known/unique/second mention/superlative.", ar:"the للمحدد أو المعروف أو الفريد أو صيغة التفضيل."},
{en:"No article: plural or uncountable nouns in general statements.", ar:"بلا أداة: الجمع وغير المعدود في العموميات."},
{en:"No article: most countries, languages, subjects, meals, sports (Egypt, English, maths, lunch).", ar:"بلا أداة: الدول واللغات والمواد والوجبات."},
{en:"the + rivers, seas, oceans, mountain ranges, plural countries (the Nile, the Alps, the Netherlands).", ar:"the مع الأنهار والبحار وسلاسل الجبال والدول الجمع."},
{en:"Use 'a' with jobs and singular descriptions: 'He is a driver.'", ar:"نستخدم a مع المهن: He is a driver."}],
examples:[
{en:"Omar is a train driver.", ar:"عمر سائق قطار."},
{en:"I saw a train and a bus; the train was faster.", ar:"رأيت قطارًا وحافلة؛ وكان القطار أسرع."},
{en:"Life is hard without water.", ar:"الحياة صعبة بدون ماء."},
{en:"The sun rises in the east.", ar:"تشرق الشمس من الشرق."},
{en:"He speaks English and Arabic.", ar:"يتحدث الإنجليزية والعربية."},
{en:"The Nile is the longest river in Africa.", ar:"النيل أطول نهر في أفريقيا."},
{en:"Pollution is a serious problem in big cities.", ar:"التلوث مشكلة خطيرة في المدن الكبرى."}],
traps:[
"The life is difficult → Life is difficult. (عمومي بلا the)",
"He is teacher → He is a teacher. (المهنة تحتاج a)",
"I like the music (عموم) → I like music.",
"The people are kind (عموم) → People are kind. / The people in my village are kind (محدد).",
"I go to the school every day → I go to school every day. (مكان بوظيفته)",
"She has an university degree → She has a university degree. (university تبدأ بصوت y)"],
story:"Omar is a train driver in Egypt. He drives a train from Cairo to Alexandria. The train is old, but the route is beautiful, and he takes breakfast at the station before work.",
exercises:[
{type:"mcq", q:"She is ____ engineer.", options:["a","an","the","(no article)"], answer:1, why:"Engineer starts with a vowel sound; job = a/an.", whyAr:"المهنة + صوت متحرك: an."},
{type:"mcq", q:"____ education is important for everyone.", options:["The","An","A","(no article)"], answer:3, why:"General uncountable noun: no article.", whyAr:"عام وغير معدود: بلا أداة."},
{type:"mcq", q:"I bought a laptop and a phone. ____ laptop was expensive.", options:["A","The","An","(no article)"], answer:1, why:"Second mention.", whyAr:"ذكر ثانٍ."},
{type:"mcq", q:"____ Nile flows through Egypt.", options:["A","An","The","(no article)"], answer:2, why:"Rivers take the.", whyAr:"الأنهار مع the."},
{type:"mcq", q:"He studies ____ in university. (the subject)", options:["the biology","a biology","biology","an biology"], answer:2, why:"Subjects: no article.", whyAr:"المواد بلا أداة."},
{type:"fill", q:"She is ____ university student. (a/an)", answer:["a"], why:"University starts with /j/ sound.", whyAr:"university تبدأ بصوت y."},
{type:"fill", q:"____ sun is a star. (a/an/the)", answer:["The","the"], why:"Unique object.", whyAr:"فريد."},
{type:"fill", q:"It was ____ best film I have ever seen. (a/an/the)", answer:["the"], why:"Superlative takes the.", whyAr:"صيغة التفضيل مع the."},
{type:"order", words:["is","he","a","train","driver"], answer:"he is a train driver", why:"Jobs take a/an.", whyAr:"المهنة مع a."},
{type:"fix", q:"The life is difficult without the water.", answer:"Life is difficult without water.", why:"General statements use zero article.", whyAr:"عمومي: بلا the."}
]},
{
id:"g11", title:"Prepositions & dependent prepositions", titleAr:"حروف الجر والحروف التابعة", level:"B2",
why:"حروف الجر هي أكتر نقطة بتتكرر في Fill in the Blanks (Reading & Writing). كمان الأخطاء فيها بتنقص نقاط Grammar في Write Essay. لازم تحفظ الكلمات مع حروف الجر الخاصة بيها.",
explainEn:"Prepositions of time: at (clock times, 'at night'), on (days and dates), in (months, years, seasons, parts of the day). Prepositions of place: at (a point), in (inside), on (a surface). 'He is at the station, in the city, on platform two.'\n\nMany verbs, adjectives and nouns need a particular preposition (dependent prepositions): depend ON, consist OF, interested IN, responsible FOR, different FROM, result IN / FROM, a reason FOR, an increase IN. These must be learned as collocations. Prepositions are followed by a noun or an -ing form: 'good at driving', not 'good at drive'.\n\nDo not translate the Arabic preposition directly: Arabic 'يعتمد على' is depend ON, but 'يتزوج من' is marry (no preposition), and 'يدخل' is enter (no preposition).",
explainAr:"حروف الجر الإنجليزية مش ليها ترجمة ثابتة. للزمن: at للساعة، on للأيام والتواريخ، in للشهور والسنين والفصول. للمكان: at لنقطة، in داخل، on على سطح. ومعظم الأفعال والصفات والأسماء ليها حرف جر خاص (dependent prepositions) لازم يتحفظ مع الكلمة: depend on، interested in، different from، responsible for. الأخطاء الشائعة: ترجمة حرف الجر حرفيًا من العربية، فنقول 'marry with' و 'enter to' و 'discuss about' وكلها غلط لأن marry و enter و discuss بلا حرف جر.",
rules:[
{en:"Time: at + clock/night; on + day/date; in + month/year/season.", ar:"زمن: at للساعة، on لليوم، in للشهر والسنة."},
{en:"Place: at + point; in + enclosed area; on + surface.", ar:"مكان: at نقطة، in داخل، on سطح."},
{en:"After a preposition use a noun or verb-ing, never the base verb.", ar:"بعد حرف الجر: اسم أو ing."},
{en:"Learn fixed pairs: depend on, consist of, interested in, responsible for, different from, increase in.", ar:"احفظ الأزواج الثابتة."},
{en:"No preposition after: discuss, enter, marry, reach, approach, mention.", ar:"لا حرف جر بعد discuss وenter وmarry وreach وmention."},
{en:"Changes in numbers: increase/rise BY 5% (amount), rise TO 50% (final level), FROM 40 TO 50.", ar:"التغيرات: by للمقدار، to للمستوى النهائي."}],
examples:[
{en:"The train leaves at 7.30 on Monday in July.", ar:"يغادر القطار الساعة 7:30 يوم الاثنين في يوليو."},
{en:"Success depends on hard work.", ar:"النجاح يعتمد على العمل الجاد."},
{en:"The committee consists of ten members.", ar:"تتكون اللجنة من عشرة أعضاء."},
{en:"She is interested in renewable energy.", ar:"هي مهتمة بالطاقة المتجددة."},
{en:"Drivers are responsible for passenger safety.", ar:"السائقون مسؤولون عن سلامة الركاب."},
{en:"There was a sharp increase in prices.", ar:"حدثت زيادة حادة في الأسعار."},
{en:"We discussed the problem for an hour.", ar:"ناقشنا المشكلة ساعة."}],
traps:[
"We discussed about the plan → We discussed the plan.",
"She entered to the room → She entered the room.",
"He married with a doctor → He married a doctor.",
"I'm interested on science → I'm interested in science.",
"Good in English → good at English.",
"different than/to (في الكتابة الرسمية) → different from."],
story:"Omar is responsible for the safety of three hundred passengers. His shift depends on the timetable, which changes in winter. Yesterday he arrived at the depot at five and discussed the new signals with his manager.",
exercises:[
{type:"mcq", q:"The meeting is ____ Tuesday ____ 10 a.m.", options:["in / at","on / at","at / on","on / in"], answer:1, why:"on + day, at + clock time.", whyAr:"on لليوم، at للساعة."},
{type:"mcq", q:"Success depends ____ hard work.", options:["of","on","in","from"], answer:1, why:"depend on.", whyAr:"depend on."},
{type:"mcq", q:"Which is correct?", options:["We discussed about it.","We discussed it.","We discussed on it.","We discussed of it."], answer:1, why:"Discuss takes no preposition.", whyAr:"discuss بلا حرف جر."},
{type:"mcq", q:"He is good ____ solving problems.", options:["in","at","on","for"], answer:1, why:"good at + -ing.", whyAr:"good at + ing."},
{type:"fill", q:"The team consists ____ eight players. (preposition)", answer:["of"], why:"consist of.", whyAr:"consist of."},
{type:"fill", q:"She is interested ____ medicine. (preposition)", answer:["in"], why:"interested in.", whyAr:"interested in."},
{type:"fill", q:"Sales rose ____ 10% last year. (amount of change)", answer:["by"], why:"by = amount.", whyAr:"by للمقدار."},
{type:"order", words:["is","responsible","for","she","safety","the"], answer:"she is responsible for the safety", why:"responsible for + noun.", whyAr:"responsible for + اسم."},
{type:"fix", q:"She entered to the room and discussed about the plan.", answer:"She entered the room and discussed the plan.", why:"Enter and discuss take no preposition.", whyAr:"enter وdiscuss بلا حرف جر."},
{type:"fix", q:"I am interested on history.", answer:"I am interested in history.", why:"interested in.", whyAr:"interested in."}
]},
{
id:"g12", title:"Gerund vs infinitive", titleAr:"المصدر بـ ing أم to + فعل", level:"B2",
why:"بتظهر في Fill in the Blanks وفي الأخطاء اللي بيتم تصحيحها في Write Essay. وبتفرق بين جملة صحيحة وغلط من غير ما تلاحظ (stop doing / stop to do).",
explainEn:"After some verbs we use the -ing form (gerund): enjoy, avoid, finish, suggest, consider, keep, mind, admit. After others we use to + infinitive: want, decide, hope, plan, agree, manage, refuse, afford. 'She enjoys driving.' 'She decided to retire.'\n\nSome verbs can take both with no change in meaning (start, begin, continue, like, love, hate). A few change meaning: 'remember to lock' (not forget a duty) vs 'remember locking' (recall the memory); 'stop to rest' (stop in order to) vs 'stop resting' (end the activity); 'try to open' (make an effort) vs 'try opening' (experiment).\n\nAfter prepositions we always use -ing: 'interested in learning', 'look forward to meeting'. Also use the gerund as a subject: 'Reading improves vocabulary.'",
explainAr:"بعد بعض الأفعال بنستخدم ing (enjoy, avoid, finish, suggest, consider, keep) وبعد أفعال تانية to + فعل (want, decide, hope, plan, agree, refuse). بعض الأفعال بتقبل الاتنين بنفس المعنى (start, like, love). وأفعال زي remember و stop و try معناها بيتغير حسب الصيغة. بعد حرف الجر دايمًا ing، حتى مع to الحرفية: look forward to meeting، مش to meet. العربية عندها مصدر واحد فنخلط بينهم. وتذكر إن enjoy ما بتاخدش to أبدًا.",
rules:[
{en:"Verb + -ing: enjoy, avoid, finish, suggest, consider, keep, mind, admit, practise.", ar:"فعل + ing: enjoy, avoid, finish, suggest, consider, keep."},
{en:"Verb + to-infinitive: want, decide, hope, plan, agree, manage, refuse, afford, promise.", ar:"فعل + to: want, decide, hope, plan, agree, manage, refuse."},
{en:"After prepositions use -ing (including 'to' as a preposition: look forward to, be used to, in addition to).", ar:"بعد حرف الجر: ing."},
{en:"Meaning changes: remember/forget/stop/try + -ing or to + infinitive.", ar:"تغير المعنى مع remember/forget/stop/try."},
{en:"Modal verbs and let/make are followed by the bare infinitive (no 'to').", ar:"بعد modals وlet/make: مصدر بدون to."},
{en:"Adjective + to-infinitive: easy to use, important to know, happy to help.", ar:"صفة + to + فعل."}],
examples:[
{en:"She enjoys driving at night.", ar:"هي تستمتع بالقيادة ليلًا."},
{en:"He decided to change jobs.", ar:"قرر أن يغير وظيفته."},
{en:"I look forward to meeting you.", ar:"أتطلع إلى مقابلتك."},
{en:"Please remember to lock the door.", ar:"من فضلك تذكر أن تغلق الباب."},
{en:"I remember locking the door; I did it at six.", ar:"أتذكر أنني أغلقت الباب؛ فعلتها في السادسة."},
{en:"He stopped to buy water.", ar:"توقف ليشتري ماء."},
{en:"Reducing emissions is essential.", ar:"خفض الانبعاثات أمر ضروري."}],
traps:[
"I enjoy to read → I enjoy reading.",
"I want go → I want to go.",
"She suggested to go → She suggested going.",
"I look forward to meet you → I look forward to meeting you.",
"He made me to wait → He made me wait.",
"I'm used to wake up early → I'm used to waking up early."],
story:"Omar enjoys driving, but he is considering retiring. He decided to take a course in training, and he looks forward to teaching new drivers. He never forgets to check the brakes.",
exercises:[
{type:"mcq", q:"She enjoys ____ novels.", options:["read","to read","reading","reads"], answer:2, why:"enjoy + -ing.", whyAr:"enjoy + ing."},
{type:"mcq", q:"They decided ____ a new house.", options:["buying","to buy","buy","bought"], answer:1, why:"decide + to.", whyAr:"decide + to."},
{type:"mcq", q:"I look forward to ____ you.", options:["see","seeing","to see","saw"], answer:1, why:"Preposition 'to' + -ing.", whyAr:"to هنا حرف جر + ing."},
{type:"mcq", q:"He stopped ____ because he was tired. (He ended the activity.)", options:["to run","running","run","ran"], answer:1, why:"stop + -ing = end the activity.", whyAr:"stop + ing = توقف عن."},
{type:"fill", q:"We managed ____ (finish) on time. (verb form)", answer:["to finish"], why:"manage + to.", whyAr:"manage + to."},
{type:"fill", q:"She avoided ____ (answer) the question. (verb form)", answer:["answering"], why:"avoid + -ing.", whyAr:"avoid + ing."},
{type:"fill", q:"He is good at ____ (solve) problems. (verb form)", answer:["solving"], why:"Preposition + -ing.", whyAr:"حرف جر + ing."},
{type:"order", words:["suggested","going","she","by","train"], answer:"she suggested going by train", why:"suggest + -ing.", whyAr:"suggest + ing."},
{type:"fix", q:"He made me to wait for an hour.", answer:"He made me wait for an hour.", why:"make + object + bare infinitive.", whyAr:"make + مفعول + فعل بدون to."},
{type:"fix", q:"I enjoy to learn new words.", answer:"I enjoy learning new words.", why:"enjoy + -ing.", whyAr:"enjoy + ing."}
]},
{
id:"g13", title:"Reported speech & reporting verbs", titleAr:"الكلام المنقول وأفعال النقل", level:"B2",
why:"في Summarize Spoken Text و Retell Lecture و Summarize Written Text بتنقل أفكار الآخرين (the speaker argues that...). أفعال النقل زي argue, claim, suggest بتخلي أسلوبك أكاديمي.",
explainEn:"In reported speech we usually move the verb one step back: present simple → past simple, present perfect → past perfect, will → would, can → could. 'I am tired' becomes 'He said he was tired.' Pronouns and time words also change: now → then, today → that day, tomorrow → the next day, here → there.\n\nWe do not always backshift when the statement is still true or is a general fact: 'The lecturer said that the Earth orbits the Sun.' For questions we use if / whether or a question word with normal word order: 'She asked if I had finished.'\n\nIn academic writing, we prefer precise reporting verbs: argue, claim, suggest, point out, emphasise, highlight, state, admit, deny, warn. Some take that-clauses, some take -ing: 'He suggested going' / 'He denied taking the money'.",
explainAr:"في الكلام المنقول بنرجّع الزمن خطوة للخلف: المضارع يصير ماضيًا، والماضي يصير ماضيًا تامًا، وwill تصير would. وتتغير الضمائر وظروف الزمن (now → then, tomorrow → the next day). في الأسئلة نستخدم if أو whether بترتيب الجملة العادي، يعني بدون did/does. العربية ما بتعملش backshift بنفس الطريقة، فبنقول He said that I am tired. وفي الأكاديمي نستخدم أفعال نقل دقيقة مثل argue وclaim وpoint out بدل say في كل مرة، وده بيرفع مستوى الكتابة.",
rules:[
{en:"Backshift: present → past, past → past perfect, will → would, can → could.", ar:"نرجع الزمن للخلف: مضارع → ماضٍ، ماضٍ → ماضٍ تام."},
{en:"Change pronouns and time/place words: now → then, tomorrow → the next day, here → there.", ar:"تتغير الضمائر وظروف الزمان والمكان."},
{en:"Reported questions: if/whether or wh-word + statement word order (no do/does/did).", ar:"السؤال المنقول: if/whether أو أداة استفهام + ترتيب الإثبات."},
{en:"'Say' has no person after it; 'tell' needs an object: 'He told me that...'", ar:"say بدون مفعول، وtell تحتاج مفعول."},
{en:"Reporting verbs + that: argue, claim, point out, state, warn. + -ing: suggest, deny, admit.", ar:"أفعال النقل: argue, claim + that؛ suggest, deny + ing."},
{en:"No backshift needed for facts that are still true.", ar:"لا backshift للحقائق الدائمة."}],
examples:[
{en:"He said he was tired.", ar:"قال إنه متعب."},
{en:"She asked me if I had finished the report.", ar:"سألتني إن كنت قد أنهيت التقرير."},
{en:"The lecturer pointed out that sleep affects memory.", ar:"أشار المحاضر إلى أن النوم يؤثر في الذاكرة."},
{en:"The author argues that cities should invest in rail.", ar:"يرى المؤلف أن على المدن الاستثمار في السكك الحديدية."},
{en:"He told me that he would call the next day.", ar:"أخبرني أنه سيتصل في اليوم التالي."},
{en:"She denied taking the money.", ar:"أنكرت أنها أخذت المال."},
{en:"The report warned that costs could rise.", ar:"حذر التقرير من أن التكاليف قد ترتفع."}],
traps:[
"He said me that he was ill → He told me that he was ill. / He said that he was ill.",
"She asked me what was my name → She asked me what my name was.",
"He asked if did I know → He asked if I knew.",
"He suggested me to go → He suggested that I go / going.",
"He said that I am late → He said that I was late."],
story:"Yesterday the manager told Omar that the timetable would change next week. Omar asked whether he would need to start earlier. The manager said he did not know yet, but he promised to inform him the next day.",
exercises:[
{type:"mcq", q:"'I am hungry,' he said. → He said he ____ hungry.", options:["were","was","has been","will be"], answer:1, why:"Backshift present to past.", whyAr:"المضارع يصير ماضيًا."},
{type:"mcq", q:"She asked me ____ I wanted tea.", options:["that","if","what","do"], answer:1, why:"Yes/no question: if / whether.", whyAr:"سؤال نعم/لا: if."},
{type:"mcq", q:"He ____ me that he would be late.", options:["said","told","spoke","suggested"], answer:1, why:"tell + object.", whyAr:"tell تحتاج مفعول."},
{type:"mcq", q:"Which verb best shows disagreement in an academic text?", options:["The author argues","The author gives","The author lists","The author goes"], answer:0, why:"argue is a precise reporting verb.", whyAr:"argue فعل نقل دقيق."},
{type:"fill", q:"'I will help you,' she said. → She said she ____ help me.", answer:["would"], why:"will → would.", whyAr:"will تصير would."},
{type:"fill", q:"'Where do you live?' he asked. → He asked me where I ____. (verb form)", answer:["lived"], why:"Backshift + statement order.", whyAr:"رجوع للماضي وترتيب الإثبات."},
{type:"fill", q:"She denied ____ (break) the window. (verb form)", answer:["breaking"], why:"deny + -ing.", whyAr:"deny + ing."},
{type:"order", words:["asked","she","if","had","I","finished","me"], answer:"she asked me if I had finished", why:"asked + object + if + clause.", whyAr:"asked + مفعول + if + جملة."},
{type:"fix", q:"He said me that he was tired.", answer:["He told me that he was tired.","He told me he was tired."], why:"say does not take a person directly.", whyAr:"say لا تأخذ مفعولًا شخصيًا."},
{type:"fix", q:"She asked me where did I go.", answer:["She asked me where I went.","She asked me where I had gone."], why:"No inversion in reported questions.", whyAr:"لا قلب في السؤال المنقول."}
]},
{
id:"g14", title:"Linking & cohesive devices", titleAr:"أدوات الربط والتماسك", level:"B2",
why:"أدوات الربط هي أساس درجة Form و Organisation في Write Essay وفي Summarize Written Text. استخدامها بشكل صحيح بيفرق جدًا في Reading: Re-order Paragraphs كمان.",
explainEn:"Linking words show the relationship between ideas. Contrast: however, nevertheless, although, whereas, while, despite, in spite of. Cause and result: because, since, as, due to, owing to, therefore, consequently, as a result. Addition: moreover, furthermore, in addition, besides. Example: for instance, for example, such as. Conclusion: in conclusion, to sum up, overall.\n\nThe type of word decides the grammar. 'Although', 'because', 'whereas' join two clauses: 'Although it rained, we went.' 'Despite' and 'because of' are followed by a noun or -ing: 'Despite the rain, we went.' 'However', 'therefore', 'moreover' start a new sentence and take a comma: 'It rained. However, we went.' Do not use 'but' together with 'although'.\n\nCohesion also uses reference words such as this, these, such and the former/the latter so the text flows from known to new information.",
explainAr:"أدوات الربط بتوضح العلاقة بين الأفكار: تضاد، سبب ونتيجة، إضافة، مثال، خلاصة. النوع بيحدد التركيب: although وbecause وwhereas بعدها جملة كاملة. despite وbecause of بعدها اسم أو ing. however وtherefore وmoreover في بداية جملة جديدة وبعدها فاصلة. أكبر فخ للعرب: استخدام although مع but في نفس الجملة (لأننا نقول 'مع أن... لكن'). وكمان استخدام despite of بدل despite. أداة الربط بتتحسب في درجة Organisation، فاستخدمها بدقة وبدون إكثار.",
rules:[
{en:"Contrast: although / while / whereas + clause; despite / in spite of + noun or -ing; however / nevertheless + comma.", ar:"تضاد: although + جملة، despite + اسم، however + فاصلة."},
{en:"Cause: because / since / as + clause; because of / due to / owing to + noun.", ar:"سبب: because + جملة، because of + اسم."},
{en:"Result: therefore, consequently, as a result (new sentence + comma).", ar:"نتيجة: therefore, consequently, as a result."},
{en:"Addition: moreover, furthermore, in addition (+ comma); besides.", ar:"إضافة: moreover, furthermore, in addition."},
{en:"Example: for example, for instance, such as (+ list, no 'etc.' after).", ar:"مثال: for example, for instance, such as."},
{en:"Conclusion: in conclusion, to sum up, overall (+ comma).", ar:"خاتمة: in conclusion, to sum up."},
{en:"Never use although and but together.", ar:"لا تجمع although وbut."}],
examples:[
{en:"Although the line is old, it carries thousands of passengers.", ar:"مع أن الخط قديم فهو ينقل آلاف الركاب."},
{en:"Despite the delay, the train arrived safely.", ar:"رغم التأخير وصل القطار بأمان."},
{en:"The signal failed. Consequently, all trains stopped.", ar:"تعطلت الإشارة. ونتيجة لذلك توقفت كل القطارات."},
{en:"Trains are cheap. Moreover, they are safe.", ar:"القطارات رخيصة. وعلاوة على ذلك فهي آمنة."},
{en:"Many cities, such as Cairo, suffer from traffic.", ar:"كثير من المدن، مثل القاهرة، تعاني من الازدحام."},
{en:"Some people prefer rail, whereas others like driving.", ar:"يفضل البعض القطار، بينما يحب آخرون القيادة."},
{en:"In conclusion, investing in public transport benefits everyone.", ar:"في الختام، يفيد الاستثمار في النقل العام الجميع."}],
traps:[
"Although it rained, but we went → Although it rained, we went.",
"Despite of the rain → Despite the rain.",
"Because the rain, we stayed → Because of the rain, we stayed.",
"In the other hand → On the other hand.",
"First of all, ... In addition, ... At last (خاتمة) → In conclusion.",
"Prices rose, however, sales fell (فاصلة منقوطة مطلوبة) → Prices rose; however, sales fell."],
story:"Although Omar's job is tiring, he loves it. The pay is good; moreover, he meets interesting people. Despite the early starts, he has never been late. In conclusion, he is a very happy driver.",
exercises:[
{type:"mcq", q:"____ the heavy rain, the match continued.", options:["Although","Despite","However","Because"], answer:1, why:"Despite + noun phrase.", whyAr:"despite + اسم."},
{type:"mcq", q:"The fare increased. ____, fewer people travelled.", options:["Although","Because of","Consequently","Despite"], answer:2, why:"Result linker starting a sentence.", whyAr:"نتيجة في بداية جملة."},
{type:"mcq", q:"____ it was cold, we went swimming.", options:["Despite","Although","However","Because"], answer:1, why:"Although + clause.", whyAr:"although + جملة."},
{type:"mcq", q:"He missed the train ____ the traffic.", options:["because","because of","so","although"], answer:1, why:"because of + noun.", whyAr:"because of + اسم."},
{type:"fill", q:"Cars pollute the air. ____, trains are cleaner. (contrast, start of sentence)", answer:["However","However,","Nevertheless","Nevertheless,"], why:"Sentence adverb of contrast.", whyAr:"أداة تضاد في بداية الجملة."},
{type:"fill", q:"Many fruits, ____ as apples and oranges, are rich in vitamin C.", answer:["such"], why:"such as introduces examples.", whyAr:"such as للأمثلة."},
{type:"fill", q:"____ conclusion, public transport should be improved.", answer:["In"], why:"In conclusion.", whyAr:"In conclusion."},
{type:"order", words:["although","tired","he","was","kept","he","working"], answer:["although he was tired he kept working","he kept working although he was tired"], why:"Although + clause, clause.", whyAr:"although + جملة، جملة."},
{type:"fix", q:"Although it was expensive, but she bought it.", answer:["Although it was expensive, she bought it.","It was expensive, but she bought it."], why:"Do not use although and but together.", whyAr:"لا تجمع although وbut."},
{type:"fix", q:"Despite of the delay, we arrived on time.", answer:"Despite the delay, we arrived on time.", why:"Despite is not followed by of.", whyAr:"despite بدون of."}
]},
{
id:"g15", title:"Comparatives, quantifiers & countable/uncountable", titleAr:"المقارنة وأدوات الكمية والمعدود وغير المعدود", level:"B1",
why:"المقارنة وأدوات الكمية ضرورية في Describe Image وفي Write Essay لما بتوصف رسم بياني (more than, fewer, a large number of). والفرق بين المعدود وغير المعدود بيظهر في كل Fill in the Blanks.",
explainEn:"Short adjectives add -er / -est (taller, the tallest). Long adjectives use more / most (more expensive, the most expensive). Irregular: good-better-best, bad-worse-worst, far-further-furthest. We use 'than' after a comparative: 'Trains are faster than buses.' Other patterns: as ... as, not as ... as, the + comparative, the + comparative ('The sooner, the better').\n\nCountable nouns can be counted (train, station) and have plurals. Uncountable nouns cannot (information, advice, equipment, traffic, news, research, furniture) and have no plural. Use many / few / fewer / a number of with countable nouns, and much / little / less / an amount of with uncountable nouns. 'A lot of' and 'plenty of' work with both. 'Few' and 'little' are negative (almost none); 'a few' and 'a little' are positive (some).",
explainAr:"الصفات القصيرة بنضيف لها er/est، والطويلة بنستخدم معها more/most. وفيه صفات شاذة (good-better-best). بعد المقارنة نستخدم than. المعدود (train) له جمع، وغير المعدود (information, advice, news, traffic, research) ما لوش جمع ولا نقول a/an معاه. أخطاء العرب: informations و advices و researches لأن المقابل العربي (معلومات، نصائح، أبحاث) جمع. many/few/fewer مع المعدود، much/little/less مع غير المعدود. few وlittle معناها 'تقريبًا مفيش' (سلبي)، و a few وa little معناها 'شوية' (إيجابي).",
rules:[
{en:"Short adjective + -er / the -est; long adjective: more / the most.", ar:"قصيرة: er/est، طويلة: more/most."},
{en:"Irregular: good-better-best, bad-worse-worst, far-further-furthest.", ar:"شاذة: good-better-best وbad-worse-worst."},
{en:"Countable: many, few, fewer, a number of; uncountable: much, little, less, an amount of.", ar:"معدود: many/few/fewer؛ غير معدود: much/little/less."},
{en:"Uncountable nouns have no plural and no 'a/an': information, advice, research, news, traffic, equipment, furniture.", ar:"غير المعدود بلا جمع وبلا a/an."},
{en:"Few / little = almost none (negative); a few / a little = some (positive).", ar:"few/little سلبي؛ a few/a little إيجابي."},
{en:"as + adjective + as for equality; the + comparative, the + comparative for parallel change.", ar:"as...as للمساواة، وthe more...the more للتوازي."}],
examples:[
{en:"Trains are faster than buses.", ar:"القطارات أسرع من الحافلات."},
{en:"This is the most important decision of my career.", ar:"هذا أهم قرار في مسيرتي."},
{en:"There is less traffic at night.", ar:"حركة المرور أقل في الليل."},
{en:"Fewer people use cars in this city than before.", ar:"عدد أقل من الناس يستخدم السيارات في هذه المدينة."},
{en:"She gave me some useful advice.", ar:"أعطتني نصيحة مفيدة."},
{en:"The more you practise, the better you become.", ar:"كلما تدربت أكثر صرت أفضل."},
{en:"A large number of students passed, but little progress was made in grammar.", ar:"نجح عدد كبير من الطلاب لكن تقدمًا ضئيلًا تحقق في القواعد."}],
traps:[
"informations / advices / researches → information / advice / research (+ some / a piece of)",
"more taller → taller; more better → better (لا نجمع الطريقتين)",
"The news are bad → The news is bad.",
"There are less people → There are fewer people.",
"He gave me an advice → He gave me some advice / a piece of advice.",
"Cairo is bigger from Giza → Cairo is bigger than Giza."],
story:"Omar gave a new driver some advice: there is much less traffic at night, so fewer delays happen. The news about the new line is good. It is the most modern track in the country, and it is cheaper to run than the old one.",
exercises:[
{type:"mcq", q:"She gave me some useful ____.", options:["advices","advice","an advice","advise"], answer:1, why:"Advice is uncountable.", whyAr:"advice غير معدود."},
{type:"mcq", q:"There are ____ cars on the road than ten years ago.", options:["less","fewer","little","much"], answer:1, why:"Countable plural: fewer.", whyAr:"معدود جمع: fewer."},
{type:"mcq", q:"This train is ____ than the old one.", options:["more fast","faster","fastest","most fast"], answer:1, why:"Short adjective + -er.", whyAr:"قصيرة + er."},
{type:"mcq", q:"The news ____ very good today.", options:["are","is","were","have been"], answer:1, why:"News is uncountable singular.", whyAr:"news مفرد."},
{type:"fill", q:"It was the ____ (bad) day of my life. (superlative)", answer:["worst"], why:"Irregular: worst.", whyAr:"شاذة: worst."},
{type:"fill", q:"There is very ____ water left in the bottle. (little/few)", answer:["little"], why:"Uncountable: little.", whyAr:"غير معدود: little."},
{type:"fill", q:"He is ____ (tall) than his brother.", answer:["taller"], why:"Comparative.", whyAr:"مقارنة."},
{type:"order", words:["is","more","than","expensive","this","that","one"], answer:"this one is more expensive than that", why:"more + adjective + than.", whyAr:"more + صفة + than."},
{type:"fix", q:"I need more informations about the course.", answer:"I need more information about the course.", why:"Information is uncountable.", whyAr:"information غير معدود."},
{type:"fix", q:"Cairo is more bigger than Giza.", answer:"Cairo is bigger than Giza.", why:"Do not use more with -er.", whyAr:"لا نجمع more وer."}
]},
{
id:"g16", title:"Sentence structure, punctuation & agreement", titleAr:"بناء الجملة والترقيم وتوافق الفاعل والفعل", level:"B2",
why:"في Write Essay و Summarize Written Text (جملة واحدة) المصحح بيشوف الـ Grammar والـ Form: جملة كاملة، ترقيم صحيح، وتوافق الفاعل مع الفعل. جملة بدون فعل أو فاصلة مكانها غلط بتكلّف نقاط.",
explainEn:"A complete English sentence needs a subject and a finite verb: 'Trains arrive.' A simple sentence has one clause; a compound sentence joins two with and, but, or, so; a complex sentence has a main clause plus a subordinate clause (although, because, which). For the one-sentence summary task, a complex sentence with a clear main idea is best.\n\nThe verb must agree with its subject: 'The number of passengers is rising', but 'A number of passengers are waiting.' Subjects joined by 'and' take a plural verb; with 'either ... or', the verb agrees with the nearer subject. Uncountable nouns take a singular verb: 'Traffic is heavy.'\n\nPunctuation: a full stop ends a sentence; use a comma after introductory phrases ('However,'), and between items in a list. Do not join two sentences with only a comma (comma splice); use a full stop, a semicolon, or a linker. A relative clause that adds extra information needs commas.",
explainAr:"الجملة الإنجليزية الكاملة لازم فيها فاعل وفعل مصرّف، عكس العربية اللي فيها الجملة الاسمية (الجو جميل) من غير فعل. فنقول The weather beautiful بالغلط؛ لازم is. الجملة البسيطة فيها فكرة واحدة، والمركبة بتربط جملتين، والمعقدة فيها جملة رئيسية وفرعية. الفعل يطابق الفاعل: The number of ... is (مفرد)، A number of ... are (جمع). غير المعدود مع فعل مفرد. أما الترقيم فأخطر خطأ هو comma splice: ربط جملتين كاملتين بفاصلة فقط، وده شائع جدًا عند الطلاب. الحل: نقطة أو فاصلة منقوطة أو أداة ربط. ولا فاصلة قبل that في الجمل المحدِّدة.",
rules:[
{en:"Every sentence needs a subject and a finite verb (Arabic nominal sentences need 'be' in English).", ar:"كل جملة تحتاج فاعلًا وفعلًا؛ الجملة الاسمية العربية تحتاج be."},
{en:"Subject-verb agreement: the number of + singular; a number of + plural; uncountable + singular.", ar:"توافق الفاعل والفعل: the number of مفرد، a number of جمع."},
{en:"Subjects joined by 'and' take a plural verb; 'either...or' agrees with the nearer subject.", ar:"فاعلان بـ and: فعل جمع؛ either...or: الأقرب."},
{en:"Avoid a comma splice: join two full sentences with a full stop, semicolon or a linker.", ar:"تجنب comma splice."},
{en:"Use a comma after introductory words/phrases and between list items; a semicolon before 'however' between sentences.", ar:"فاصلة بعد المقدمات وبين عناصر القائمة."},
{en:"Avoid fragments: 'Because it rained.' is not a sentence alone.", ar:"تجنب الجمل الناقصة."}],
examples:[
{en:"Although the line is old, it remains very safe.", ar:"مع أن الخط قديم فإنه يبقى آمنًا جدًا."},
{en:"The number of passengers is rising every year.", ar:"عدد الركاب يرتفع كل عام."},
{en:"A number of passengers are waiting on the platform.", ar:"عدد من الركاب ينتظرون على الرصيف."},
{en:"Omar and his colleague work night shifts.", ar:"عمر وزميله يعملان في الورديات الليلية."},
{en:"Neither the driver nor the passengers were hurt.", ar:"لم يُصب السائق ولا الركاب."},
{en:"The report was long; however, it was clear.", ar:"كان التقرير طويلًا؛ لكنه كان واضحًا."},
{en:"Trains are fast, safe, and cheap.", ar:"القطارات سريعة وآمنة ورخيصة."}],
traps:[
"The weather very hot → The weather is very hot. (الجملة الاسمية العربية تحتاج be)",
"The trains is late → The trains are late. / The train is late.",
"The news are good → The news is good.",
"He was tired, he went home. → He was tired, so he went home. (comma splice)",
"The number of people are rising → The number of people is rising.",
"Because it rained. We stayed home. → Because it rained, we stayed home. (fragment)"],
story:"The number of passengers is rising, but the trains are old. The manager and the engineers meet every Monday. Omar was tired; however, he finished the shift.",
exercises:[
{type:"mcq", q:"The number of students ____ increasing.", options:["are","is","were","have been"], answer:1, why:"The number of takes a singular verb.", whyAr:"the number of مفرد."},
{type:"mcq", q:"A number of students ____ absent.", options:["is","was","are","has been"], answer:2, why:"A number of takes plural.", whyAr:"a number of جمع."},
{type:"mcq", q:"Which sentence is correct?", options:["She was late, she missed the train.","She was late; she missed the train.","She was late she missed the train.","She was late, and, she missed the train."], answer:1, why:"A semicolon can join two sentences.", whyAr:"الفاصلة المنقوطة تربط جملتين."},
{type:"mcq", q:"The weather ____ very hot in July.", options:["very","is","are","be"], answer:1, why:"English needs a verb 'be'.", whyAr:"الإنجليزية تحتاج be."},
{type:"fill", q:"Neither the driver nor the passengers ____ (be) injured. (past form)", answer:["were"], why:"Verb agrees with the nearer subject (passengers).", whyAr:"يطابق الأقرب."},
{type:"fill", q:"Traffic ____ (be) heavy at 8 a.m. (present form)", answer:["is"], why:"Uncountable: singular.", whyAr:"غير معدود: مفرد."},
{type:"fill", q:"Omar and his friend ____ (work) at the depot. (present form)", answer:["work"], why:"Subjects joined by and: plural.", whyAr:"and: جمع."},
{type:"order", words:["although","safe","it","old","is","the","train","is"], answer:["although the train is old it is safe","it is safe although the train is old"], why:"Complex sentence: subordinate + main.", whyAr:"جملة معقدة."},
{type:"fix", q:"The traffic very heavy in Cairo.", answer:"The traffic is very heavy in Cairo.", why:"Missing verb be.", whyAr:"ينقص فعل be."},
{type:"fix", q:"It rained heavily, we cancelled the trip.", answer:["It rained heavily, so we cancelled the trip.","It rained heavily; we cancelled the trip.","It rained heavily. We cancelled the trip.","It rained heavily, and we cancelled the trip."], why:"Comma splice: add a linker.", whyAr:"أضف أداة ربط (so) أو استخدم نقطة."}
]}
];
